//! Irregular atlas regions, normalized top-left UVs; no automatic animation authoring.
use crate::{Animation,Object};
use std::{path::{Path,PathBuf},fs};
pub fn valid_region([x,y,w,h]:[f32;4])->bool{[x,y,w,h].iter().all(|v|v.is_finite())&&x>=0.&&y>=0.&&w>0.&&h>0.&&x+w<=1.000001&&y+h<=1.000001}
/// Shelf packing with a one-pixel transparent border per image. Input order is frame order.
pub fn pack_atlas_frames(paths:&[PathBuf],root:&Path)->Result<Object,String>{
 if paths.is_empty()||paths.len()>256{return Err("Select 1–256 frame images".into());}
 let mut frames=Vec::new();let mut bytes=0u64;
 for path in paths{let mut reader=image::ImageReader::open(path).map_err(|e|e.to_string())?.with_guessed_format().map_err(|e|e.to_string())?;let mut limits=image::Limits::default();limits.max_image_width=Some(2046);limits.max_image_height=Some(2046);limits.max_alloc=Some(32*1024*1024);reader.limits(limits);let img=reader.decode().map_err(|e|e.to_string())?.to_rgba8();if img.width()==0||img.height()==0{return Err("Empty frame".into());}bytes+=u64::from(img.width())*u64::from(img.height())*4;if bytes>64*1024*1024{return Err("Frame memory limit: 64 MiB".into());}frames.push(img);}
 let natural:Vec<usize>=(0..frames.len()).collect();let mut sorted=natural.clone();sorted.sort_by_key(|&i|std::cmp::Reverse(frames[i].height()));let mut best=None;let min_width=frames.iter().map(|f|f.width()+2).max().unwrap_or(1);let mut wide=natural.clone();wide.sort_by_key(|&i|std::cmp::Reverse(frames[i].width()));for width in [256,512,768,1024,1536,2048]{if width<min_width{continue;}for order in [&natural,&sorted,&wide]{if let Some(candidate)=shelf(&frames,order,width){if best.as_ref().is_none_or(|(_,w,h):&(Vec<[u32;4]>,u32,u32)|u64::from(candidate.1)*u64::from(candidate.2)<u64::from(*w)*u64::from(*h)){best=Some(candidate);}}}}let (rects,width,height)=best.ok_or("Atlas exceeds 2048 × 4096")?;let mut atlas=image::RgbaImage::new(width,height);for (img,r) in frames.iter().zip(&rects){image::imageops::replace(&mut atlas,img,i64::from(r[0]),i64::from(r[1]));}
 let rel=format!("assets/atlas-{}.png",uuid::Uuid::new_v4());fs::create_dir_all(root.join("assets")).map_err(|e|e.to_string())?;atlas.save(root.join(&rel)).map_err(|e|e.to_string())?;
 let metadata=serde_json::json!({"schema":1,"image":rel,"width":width,"height":height,"frames":rects.iter().zip(paths).enumerate().map(|(index,(r,p))|serde_json::json!({"index":index,"source":p.file_name().unwrap_or_default().to_string_lossy(),"rect":r})).collect::<Vec<_>>()});
 let sidecar=root.join(&rel).with_extension("atlas.json");if let Err(e)=fs::write(&sidecar,serde_json::to_vec_pretty(&metadata).map_err(|e|e.to_string())?){let _=fs::remove_file(root.join(&rel));return Err(e.to_string());}
 let regions=rects.iter().map(|r|[r[0] as f32/width as f32,r[1] as f32/height as f32,r[2] as f32/width as f32,r[3] as f32/height as f32]).collect();
 let mut o=Object::new("Atlas animation",[0.;2],[frames[0].width() as f32,frames[0].height() as f32],[255;4]);o.sprite=Some(rel);o.animation=Animation{frames:paths.len() as u32,regions,..Default::default()};o.clips.insert(o.clip_name.clone(),o.animation.clone());Ok(o)
}
#[cfg(test)]mod tests{use super::*;#[test]fn irregular_uv(){let a=Animation{frames:2,regions:vec![[0.,0.,0.25,0.5],[0.5,0.25,0.25,0.25]],fps:1.,..Default::default()};assert_eq!(a.frame(1.1),1);assert_eq!(a.uv(1.1)[2],[0.75,0.5]);assert!(!valid_region([0.9,0.,0.2,1.]));}#[test]fn pack_roundtrip(){let root=std::env::temp_dir().join(uuid::Uuid::new_v4().to_string());fs::create_dir_all(&root).unwrap();let a=root.join("a.png");let b=root.join("b.png");image::RgbaImage::new(13,7).save(&a).unwrap();image::RgbaImage::new(5,19).save(&b).unwrap();let o=pack_atlas_frames(&[a,b],&root).unwrap();assert_eq!(o.animation.regions.len(),2);assert!(o.animation.regions.iter().copied().all(valid_region));assert!(root.join(o.sprite.unwrap()).exists());fs::remove_dir_all(root).unwrap();}}

/// Edit a normalized atlas rectangle without allowing it outside the texture.
pub fn drag_region(r:[f32;4],delta:[f32;2],pixels:[u32;2],resize:bool)->[f32;4]{
 if !valid_region(r)||!delta.iter().all(|v|v.is_finite())||pixels.contains(&0){return r;}
 let [x,y,w,h]=r;let min_w=(1./pixels[0] as f32).min((1.-x).max(f32::EPSILON));let min_h=(1./pixels[1] as f32).min((1.-y).max(f32::EPSILON));
 if resize{[x,y,(w+delta[0]).clamp(min_w,(1.-x).max(min_w)),(h+delta[1]).clamp(min_h,(1.-y).max(min_h))]}else{[(x+delta[0]).clamp(0.,(1.-w).max(0.)),(y+delta[1]).clamp(0.,(1.-h).max(0.)),w,h]}
}
pub fn snap_region_pixels(r:[f32;4],pixels:[u32;2])->[f32;4]{if !valid_region(r)||pixels.contains(&0){return r;}let w=pixels[0] as f32;let h=pixels[1] as f32;let x=(r[0]*w).round().clamp(0.,w-1.);let y=(r[1]*h).round().clamp(0.,h-1.);let right=((r[0]+r[2])*w).round().clamp(x+1.,w);let bottom=((r[1]+r[3])*h).round().clamp(y+1.,h);[x/w,y/h,(right-x)/w,(bottom-y)/h]}
#[cfg(test)]mod edit_tests{use super::*;#[test]fn bounded_drag(){let r=[0.2,0.3,0.4,0.5];let moved=drag_region(r,[2.,-2.],[100,100],false);assert!(valid_region(moved));assert_eq!(moved[1],0.);let small=drag_region(r,[-2.,-2.],[100,100],true);assert_eq!(small[2],0.01);assert!(valid_region(small));}#[test]fn pixel_snap(){assert_eq!(snap_region_pixels([0.11,0.29,0.36,0.43],[10,10]),[0.1,0.3,0.4,0.4]);}}

/// Trim transparent pixels within one atlas region; no texture mutation. Returns original when fully transparent.
pub fn trim_alpha_region(img:&image::RgbaImage,r:[f32;4],threshold:u8)->Option<[f32;4]>{if !valid_region(r)||img.width()==0||img.height()==0{return None;}let w=img.width();let h=img.height();let r=snap_region_pixels(r,[w,h]);let x=(r[0]*w as f32).round() as u32;let y=(r[1]*h as f32).round() as u32;let right=((r[0]+r[2])*w as f32).round().min(w as f32) as u32;let bottom=((r[1]+r[3])*h as f32).round().min(h as f32) as u32;let(mut min_x,mut min_y,mut max_x,mut max_y)=(right,bottom,0,0);for py in y..bottom{for px in x..right{if img.get_pixel(px,py)[3]>threshold{min_x=min_x.min(px);min_y=min_y.min(py);max_x=max_x.max(px+1);max_y=max_y.max(py+1);}}}if min_x>=max_x||min_y>=max_y{return None;}Some([min_x as f32/w as f32,min_y as f32/h as f32,(max_x-min_x) as f32/w as f32,(max_y-min_y) as f32/h as f32])}
#[cfg(test)]mod trim_tests{use super::*;#[test]fn alpha_bounds(){let mut img=image::RgbaImage::new(10,10);img.put_pixel(3,4,image::Rgba([255,255,255,255]));img.put_pixel(9,9,image::Rgba([255,255,255,255]));assert_eq!(trim_alpha_region(&img,[0.,0.,0.8,0.8],0),Some([0.3,0.4,0.1,0.1]));assert!(trim_alpha_region(&img,[0.,0.,0.2,0.2],0).is_none());}}

fn shelf(frames:&[image::RgbaImage],order:&[usize],limit:u32)->Option<(Vec<[u32;4]>,u32,u32)>{let mut rects=vec![[0;4];frames.len()];let(mut x,mut y,mut row,mut width)=(0u32,0u32,0u32,0u32);for &i in order{let img=&frames[i];let(w,h)=(img.width()+2,img.height()+2);if x+w>limit{x=0;y+=row;row=0;}if y+h>4096{return None;}rects[i]=[x+1,y+1,w-2,h-2];x+=w;row=row.max(h);width=width.max(x);}Some((rects,width,y+row))}
/// Preserve visual position and pixel scale for a single-frame sprite; physics size is not independent.
pub fn compensate_trim(old:[f32;4],new:[f32;4],size:[f32;2],pivot:[f32;2])->Option<([f32;2],[f32;2])>{if !valid_region(old)||!valid_region(new)||size.iter().any(|s|!s.is_finite()||*s<=0.)||pivot.iter().any(|v|!v.is_finite())||new[0]+1e-6<old[0]||new[1]+1e-6<old[1]||new[0]+new[2]>old[0]+old[2]+1e-6||new[1]+new[3]>old[1]+old[3]+1e-6{return None;}let ratio=[new[2]/old[2],new[3]/old[3]];let offset=[(new[0]+new[2]*0.5-old[0]-old[2]*0.5)/old[2],-(new[1]+new[3]*0.5-old[1]-old[3]*0.5)/old[3]];Some(([size[0]*ratio[0],size[1]*ratio[1]],[(pivot[0]-offset[0])/ratio[0],(pivot[1]-offset[1])/ratio[1]]))}
#[cfg(test)]mod compensation_tests{use super::*;#[test]fn preserves_original_world_pixel(){let (s,p)=compensate_trim([0.,0.,1.,1.],[0.25,0.25,0.5,0.25],[100.,100.],[0.,0.]).unwrap();assert_eq!(s,[50.,25.]);assert_eq!(p,[0.,-0.5]);}}

/// Compose a trimmed UV region into the frame's existing logical rectangle.
/// Repeated trims retain scale and position without modifying the object or collider.
pub fn trim_frame_preserving_geometry(a:&mut Animation,i:usize,new:[f32;4])->bool{
 let Some(&old)=a.regions.get(i) else{return false;};
 if !valid_region(old)||!valid_region(new)||new[0]+1e-6<old[0]||new[1]+1e-6<old[1]||new[0]+new[2]>old[0]+old[2]+1e-6||new[1]+new[3]>old[1]+old[3]+1e-6{return false;}
 let base=a.frame_geometry.get(&(i as u32)).copied().filter(|g|valid_region(*g)).unwrap_or([0.,0.,1.,1.]);
 let g=[base[0]+(new[0]-old[0])/old[2]*base[2],base[1]+(new[1]-old[1])/old[3]*base[3],new[2]/old[2]*base[2],new[3]/old[3]*base[3]];
 if !valid_region(g){return false;}a.regions[i]=new;a.frame_geometry.insert(i as u32,g);true
}
#[cfg(test)]mod geometry_tests{use super::*;#[test]fn repeated_trim(){let mut a=Animation{regions:vec![[0.,0.,1.,1.],[0.,0.,1.,1.]],..Default::default()};assert!(trim_frame_preserving_geometry(&mut a,1,[0.25,0.25,0.5,0.5]));assert!(trim_frame_preserving_geometry(&mut a,1,[0.375,0.375,0.25,0.25]));assert_eq!(a.frame_geometry[&1],[0.375,0.375,0.25,0.25]);assert!(!a.frame_geometry.contains_key(&0));assert!(!trim_frame_preserving_geometry(&mut a,1,[0.,0.,1.,1.]));let b:Animation=serde_json::from_str(&serde_json::to_string(&a).unwrap()).unwrap();assert_eq!(a,b);}}

/// Explicit metadata synchronization, isolated by object ID so shared atlas users do not overwrite one another.
/// Original import metadata and source image are left untouched.
pub fn sync_atlas_metadata(root:&Path,o:&Object)->Result<String,String>{
 use std::io::Write;
 let rel=o.sprite.as_deref().ok_or("No sprite")?;if !crate::valid_asset(rel){return Err("Invalid sprite path".into());}let base=root.join("assets").canonicalize().map_err(|e|e.to_string())?;let path=root.join(rel).canonicalize().map_err(|e|e.to_string())?;if !path.starts_with(&base){return Err("Sprite outside assets".into());}let (width,height)=image::image_dimensions(&path).map_err(|e|e.to_string())?;if width==0||height==0{return Err("Empty image".into());}
 let mut clips=o.clips.clone();clips.insert(o.clip_name.clone(),o.animation.clone());if clips.len()>128{return Err("Clip limit".into());}
 let mut items=serde_json::Map::new();let mut total=0u32;for (name,a) in &clips{total=total.saturating_add(a.total_frames());if total>16384||a.regions.iter().any(|r|!valid_region(*r))||a.frame_geometry.iter().any(|(&i,g)|i>=a.total_frames()||!valid_region(*g)){return Err(format!("Invalid region, geometry or metadata frame budget in {name}"));}let grid;let regions=if a.regions.is_empty(){let c=a.columns.max(1);let r=a.rows.max(1);grid=(0..a.total_frames()).map(|i|[(i%c) as f32/c as f32,(i/c) as f32/r as f32,1./c as f32,1./r as f32]).collect::<Vec<_>>();&grid}else{&a.regions};let frames:Vec<_>=regions.iter().enumerate().map(|(i,r)|{let x=(r[0]*width as f32).round() as u32;let y=(r[1]*height as f32).round() as u32;let right=((r[0]+r[2])*width as f32).round().min(width as f32) as u32;let bottom=((r[1]+r[3])*height as f32).round().min(height as f32) as u32;serde_json::json!({"index":i,"rect":[x,y,right.saturating_sub(x),bottom.saturating_sub(y)],"geometry":a.frame_geometry.get(&(i as u32))})}).collect();items.insert(name.clone(),serde_json::json!({"animation":a,"frames":frames}));}
 let data=serde_json::to_vec_pretty(&serde_json::json!({"schema":2,"object":o.id,"image":rel,"width":width,"height":height,"pivot":o.motion.pivot,"logical_size":o.size,"clips":items})).map_err(|e|e.to_string())?;if data.len()>8*1024*1024{return Err("Atlas metadata exceeds 8 MiB".into());}
 let filename=format!("atlas-state-{}.json",o.id);let target=base.join(&filename);let temp=base.join(format!("{}.tmp",uuid::Uuid::new_v4()));let result=(||->Result<(),String>{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&temp).map_err(|e|e.to_string())?;f.write_all(&data).and_then(|_|f.sync_all()).map_err(|e|e.to_string())?;drop(f);fs::rename(&temp,&target).map_err(|e|e.to_string())?;Ok(())})();if result.is_err(){let _=fs::remove_file(&temp);}result?;Ok(format!("assets/{filename}"))
}
#[cfg(test)]mod metadata_tests{use super::*;#[test]fn per_object_metadata(){let root=std::env::temp_dir().join(uuid::Uuid::new_v4().to_string());fs::create_dir_all(root.join("assets")).unwrap();image::RgbaImage::new(32,32).save(root.join("assets/sheet.png")).unwrap();let mut o=Object::new("a",[0.;2],[32.;2],[255;4]);o.sprite=Some("assets/sheet.png".into());o.animation.regions=vec![[0.,0.,0.5,0.5]];let path=sync_atlas_metadata(&root,&o).unwrap();o.animation.regions[0]=[0.5,0.5,0.5,0.5];assert_eq!(sync_atlas_metadata(&root,&o).unwrap(),path);let v:serde_json::Value=serde_json::from_slice(&fs::read(root.join(path)).unwrap()).unwrap();assert_eq!(v["clips"][&o.clip_name]["frames"][0]["rect"],serde_json::json!([16,16,16,16]));fs::remove_dir_all(root).unwrap();}}
